513→// ── CLI ───────────────────────────────────────────────────────────
514→if (import.meta.url === `file://${process.argv[1]}`) {
515→  const args = process.argv.slice(2);
516→  const capturePaths = args.filter((a) => !a.startsWith("--"));
517→  if (capturePaths.length === 0) {
518→    console.error("usage: node verify.mjs <capture.jsonl ...> [--json] [--service-log=F] [--reachability=F]");
519→    process.exit(2);
520→  }
521→  const opt = (name) => (args.find((a) => a.startsWith(`--${name}=`)) ?? "").slice(name.length + 3) || null;
522→  const serviceLog = opt("service-log");
523→  const reachPath = opt("reachability");
524→  const opts = {
525→    serviceRows: serviceLog ? parseJsonl(readFileSync(serviceLog, "utf8")) : [],
526→    reachability: reachPath ? JSON.parse(readFileSync(reachPath, "utf8")) : null,
527→  };
528→  const result = verify(capturePaths.flatMap((p) => parseJsonl(readFileSync(p, "utf8"))), opts);
529→  console.log(args.includes("--json") ? JSON.stringify(result, null, 2) : render(result));
530→  process.exit(result.verdict === PASS ? 0 : result.verdict === FAIL ? 1 : 2);
531→}
