  1→/**
  2→ * Acceptance tests.
  3→ *
  4→ * Each case is a rule that sounds reasonable and gets the verdict wrong: "some
  5→ * call returned 200", "it succeeded at some point", "it never failed", "there
  6→ * was no successful call so it failed".
  7→ */
  8→
  9→import { test } from "node:test";
 10→import assert from "node:assert/strict";
 11→
 12→import { verify, attempts, outcomeOfAttempt, PASS, FAIL, ERROR } from "./verify.mjs";
 13→
 14→import { TASK_MARKER } from "./verify.mjs";
 15→
 16→const TARGET_OK = "http://127.0.0.1:47318/skill-bridge/v3/skill/search";
 17→const TARGET_BAD = "http://10.244.7.19:8096/skill-bridge/v3/skill/search";
 18→const READ = "http://127.0.0.1:8096/skill-bridge/v3/skill/get-by-name";
 19→
 20→const OK_BODY = 'Stdout: {"code":0,"message":"ok","data":{"items":[]}}\nHTTP_CODE: 200';
 21→const TIMEOUT = "Exit code: 28\nStdout: \nStderr: curl: (28) Operation timed out after 75000 ms";
 22→
 23→/** The command the model wrote, as it appears in the tool call's arguments. */
 24→const cmdFor = (url, query) =>
 25→  JSON.stringify({ command: `curl -sSk -X POST ${url} -d '{"query":"${query}"}'` });
 26→
 27→/**
 28→ * A captured session. Each step is a call the model made, optionally with the
 29→ * result that came back — `body: null` means the result was never captured,
 30→ * which the attempt list has to survive.
 31→ */
 32→function session(steps) {
 33→  const messages = [{ role: "user", content: "do the task" }];
 34→  steps.forEach(({ url, body, query = TASK_MARKER }, i) => {
 35→    messages.push({
 36→      role: "assistant",
 37→      tool_calls: [{ id: `c${i}`, function: { name: "Bash", arguments: cmdFor(url, query) } }],
 38→    });
 39→    if (body !== null) {
 40→      messages.push({
 41→        role: "tool", tool_call_id: `c${i}`,
 42→        content: `Command: curl -sSk -X POST ${url} -d '{"query":"${query}"}'\n${body}`,
 43→      });
 44→    }
 45→  });
 46→  return [{
 47→    event: "http.request",
 48→    requestId: "req-1",
 49→    timestamp: "2026-09-05T12:00:00Z",
 50→    headers: { "x-conversation-id": "conv-1" },
 51→    body: { json: { messages } },
 52→  }];
 53→}
 54→
 55→// ── the four outcomes ─────────────────────────────────────────────
 56→
 57→test("a successful prerequisite read does not make a timed-out target pass", () => {
 58→  // "Some call in this session returned 200" is true here, and the 200 is the
 59→  // model fetching the asset that told it which address to use.
 60→  const r = verify(session([
 61→    { url: READ, body: OK_BODY },
 62→    { url: TARGET_BAD, body: TIMEOUT },
 63→  ]));
 64→  assert.equal(r.verdict, FAIL);
 65→  assert.equal(r.attempts.length, 1, "reading the asset is a bridge call too, but it is not the target");
 66→  assert.match(r.reason, /timed out/);
 67→});
 68→
 69→test("succeeding early and failing at the end is a failure", () => {
 70→  // "It succeeded at some point" is true and the run did not work.
 71→  const r = verify(session([
 72→    { url: TARGET_OK, body: OK_BODY },
 73→    { url: TARGET_OK, body: TIMEOUT },
 74→  ]));
 75→  assert.equal(r.verdict, FAIL);
 76→  assert.match(r.reason, /despite 1 earlier success/);
 77→});
 78→
 79→test("failing first and succeeding last is a pass", () => {
 80→  // "It never failed" is false and the run did work. Retrying after an error is
 81→  // ordinary behaviour; a rule that punishes it is measuring neatness.
 82→  const r = verify(session([
 83→    { url: TARGET_BAD, body: TIMEOUT },
 84→    { url: TARGET_OK, body: OK_BODY },
 85→  ]));
 86→  assert.equal(r.verdict, PASS);
 87→  assert.match(r.reason, /after 1 earlier failure/);
 88→});
 89→
 90→test("never attempting the target is an error, not a failure", () => {
 91→  // A run that never tried is not a run that tried and failed. Collapsing them
 92→  // turns a broken harness into evidence about the asset.
 93→  const r = verify(session([{ url: READ, body: OK_BODY }]));
 94→  assert.equal(r.verdict, ERROR);
 95→  assert.match(r.reason, /never carried out/);
 96→});
 97→
 98→test("an unreadable outcome is an error, not a failure", () => {
 99→  const r = verify(session([{ url: TARGET_OK, body: "Stdout: \n" }]));
100→  assert.equal(r.verdict, ERROR);
101→  assert.match(r.reason, /could not be read/);
102→});
103→
104→// ── reading one attempt ───────────────────────────────────────────
105→
106→test("a 200 carrying a service error is not a success", () => {
107→  // curl calls it success; the envelope refuses. The envelope is right.
108→  const r = outcomeOfAttempt('Stdout: {"code":40101,"message":"session not initialized"}\nHTTP_CODE: 200');
109→  assert.equal(r.ok, false);
110→  assert.match(r.why, /40101/);
111→});
112→
113→test("a timeout is read from the exit code, not from prose", () => {
114→  assert.equal(outcomeOfAttempt(TIMEOUT).ok, false);
115→  assert.match(outcomeOfAttempt(TIMEOUT).why, /timed out/);
116→});
117→
118→test("a refused connection is a failure, not an unreadable outcome", () => {
119→  const r = outcomeOfAttempt("Exit code: 7\nStderr: curl: (7) Failed to connect to 127.0.0.1 port 52907");
120→  assert.equal(r.ok, false);
121→});
122→
123→test("an empty output is unreadable rather than failed", () => {
124→  assert.equal(outcomeOfAttempt("Command: curl x\nStdout: \n").ok, null);
125→});
126→
127→// ── which calls count as attempts ─────────────────────────────────
128→
129→test("the command decides the target, never the response", () => {
130→  // A response that quotes the address is not an attempt at it — the same
131→  // request/response confusion that made the first verifier report three
132→  // channels as used.
133→  const r = verify([{
134→    event: "http.request",
135→    requestId: "req-1",
136→    timestamp: "2026-09-05T12:00:00Z",
137→    headers: { "x-conversation-id": "conv-1" },
138→    body: { json: { messages: [
139→      { role: "assistant", tool_calls: [{ id: "c0", function: { name: "Bash", arguments: JSON.stringify({ command: "cat notes.md" }) } }] },
140→      { role: "tool", tool_call_id: "c0", content: `Command: cat notes.md\nStdout: check ${TARGET_OK} with query ${TASK_MARKER}` },
141→    ] } },
142→  }]);
143→  assert.equal(r.verdict, ERROR);
144→  assert.equal(r.attempts.length, 0);
145→});
146→
147→test("the address is kept, so which asset was followed stays visible", () => {
148→  const tried = attempts(session([
149→    { url: TARGET_BAD, body: TIMEOUT },
150→    { url: TARGET_OK, body: OK_BODY },
151→  ]));
152→  assert.deepEqual(tried.map((a) => `${a.host}:${a.port}`), ["10.244.7.19:8096", "127.0.0.1:47318"]);
153→});
154→
155→test("a repeated result across turns is one attempt", () => {
156→  // Messages accumulate, so the same call reappears in every later request.
157→  const first = session([{ url: TARGET_OK, body: OK_BODY }]);
158→  const second = JSON.parse(JSON.stringify(first[0]));
159→  second.requestId = "req-2";
160→  second.timestamp = "2026-09-05T12:01:00Z";
161→  assert.equal(attempts([...first, second]).length, 1);
162→});
163→
164→// ── the two ways a PASS was reported that should not have been ────
165→
166→test("searching for the guidance asset is not carrying out the task", () => {
167→  // The task's first step is a search — for the asset that documents the
168→  // address. Accepting any skill/search scores discovery as execution: the
169→  // search succeeds, reading the guidance asset fails, the address is never
170→  // used, and the run passes.
171→  const r = verify(session([
172→    { url: TARGET_OK, body: OK_BODY, query: "bridge address convention" }, // finding the asset
173→    { url: READ, body: "Exit code: 7\nStderr: curl: (7) Failed to connect" }, // reading it failed
174→  ]));
175→
176→  assert.equal(r.verdict, ERROR);
177→  assert.equal(r.attempts.length, 0, "neither call carries the task marker");
178→  assert.match(r.reason, /never carried out/);
179→});
180→
181→test("a marked request against the documented address is the task", () => {
182→  const r = verify(session([
183→    { url: TARGET_OK, body: OK_BODY, query: "bridge address convention" },
184→    { url: TARGET_OK, body: OK_BODY },
185→  ]));
186→  assert.equal(r.verdict, PASS);
187→  assert.equal(r.attempts.length, 1, "only the marked call counts");
188→});
189→
190→test("a last call whose result was never captured is an error, not the previous verdict", () => {
191→  // Walking results only makes such a call invisible, so the verdict silently
192→  // falls back to the earlier success — a PASS for a run whose last act was to
193→  // fire at the wrong address.
194→  const r = verify(session([
195→    { url: TARGET_OK, body: OK_BODY },
196→    { url: TARGET_BAD, body: null },
197→  ]));
198→
199→  assert.equal(r.verdict, ERROR);
200→  assert.equal(r.attempts.length, 2, "the call is in the list even with nothing known about it");
201→  assert.equal(r.attempts[1].ok, null);
202→  assert.match(r.reason, /could not be read/);
203→});
204→
205→test("an earlier call with no result does not sink a completed run", () => {
206→  // Only the last attempt decides. A missing result in the middle is a
207→  // collection gap, not a failure of the run.
208→  const r = verify(session([
209→    { url: TARGET_BAD, body: null },
210→    { url: TARGET_OK, body: OK_BODY },
211→  ]));
212→  assert.equal(r.verdict, PASS);
213→  assert.equal(r.attempts[0].ok, null);
214→});
215→
216→test("attempts stay in the order the model made them", () => {
217→  const r = verify(session([
218→    { url: TARGET_BAD, body: TIMEOUT },
219→    { url: TARGET_OK, body: OK_BODY },
220→    { url: TARGET_BAD, body: TIMEOUT },
221→  ]));
222→  assert.deepEqual(r.attempts.map((a) => a.host), ["10.244.7.19", "127.0.0.1", "10.244.7.19"]);
223→  assert.equal(r.verdict, FAIL, "the last one decides");
224→});
225→
226→// ---------------------------------------------------------------------------
227→// 追踪头 —— 新的判别性 token(2026-09-09)
228→//
229→// 旧口径的判别值是地址。地址可以从部署环境读出来,所以"命中"不足以说明读了资产。
230→// 新口径:每条资产各自规定一个追踪头的值,采用该资产就必然在命令里留下它。
231→//
232→// 验收**不看**这个值:PASS / FAIL 仍然只由目标调用的成败决定。验收独立于归因是
233→// 硬约束——记录它,不用它判。
234→// ---------------------------------------------------------------------------
235→import { traceOf } from "./verify.mjs";
236→
237→const cmdWith = (addr, trace) =>
238→  `curl -sS -X POST 'http://${addr}/skill-bridge/v3/skill/search' -H 'content-type: application/json'` +
239→  (trace ? ` -H 'x-team-trace: ${trace}'` : "") +
240→  ` -d '{"query":"team-bridge-reachability"}'`;
241→
242→test("追踪头的值被读出来", () => {
243→  assert.equal(traceOf(cmdWith("127.0.0.1:47318", "bt-testonly-rightval")), "bt-testonly-rightval");
244→});
245→
246→test("没带追踪头 → 空,不是猜一个", () => {
247→  assert.equal(traceOf(cmdWith("127.0.0.1:47318", null)), "");
248→});
249→
250→test("大小写与空格不影响读取", () => {
251→  assert.equal(traceOf(`-H "X-Team-Trace:   bt-testonly-wrongval"`), "bt-testonly-wrongval");
252→});
253→
254→test("尝试记录里带上追踪值,并且它不参与判定", () => {
255→  const mk = (id, addr, trace, out) => ([
256→    { event: "http.request", timestamp: "2026-09-09T00:00:0" + id + "Z", headers: { "x-conversation-id": "c1" },
257→      body: { json: { messages: [
258→        { role: "assistant", tool_calls: [{ id: `call_${id}`, function: { arguments: JSON.stringify({ command: cmdWith(addr, trace) }) } }] },
259→        { role: "tool", tool_call_id: `call_${id}`, content: out },
260→      ] } } },
261→  ]);
262→  const got = attempts(mk("1", "127.0.0.1:47318", "bt-testonly-rightval", 'Exit code: 0\n{"code":0}'));
263→  assert.equal(got.length, 1);
264→  assert.equal(got[0].value, "bt-testonly-rightval", "采纳判定要读它");
265→  assert.equal(got[0].ok, true);
266→
267→  const noTrace = attempts(mk("2", "127.0.0.1:47318", null, 'Exit code: 0\n{"code":0}'));
268→  assert.equal(noTrace[0].value, "", "没带就是空");
269→  assert.equal(noTrace[0].ok, true, "验收不因为缺追踪头而改判");
270→});
271→

  1→/**
  2→ * Acceptance when one tool call carries more than one request, and when the
  3→ * final requests were issued together.
  4→ *
  5→ * Batch 4 run 5 (20260910T232627Z-gate-off): one Bash command dialled
  6→ * 127.0.0.1:47318 (code 0, confirmed by the next tool call parsing
  7→ * /tmp/resp_b.txt) and then 10.244.7.19:8096 (curl 28 after 12 s). The old
  8→ * parser made one attempt keyed to the first URL and read one outcome from the
  9→ * combined text: "127.0.0.1:47318 timed out" — false in detail. Runs 1 and 3
 10→ * issued the wrong and the right dial as two tool calls in ONE model message;
 11→ * the service log shows the right one answered 53 ms after the message while
 12→ * the wrong one ran into its 20 s timeout, so "the last attempt" cannot be
 13→ * read off the text order.
 14→ *
 15→ * Four boundaries (2026-09-11):
 16→ *   1. every actual request binds its own address, trace and outcome; one tool
 17→ *      call may hold several;
 18→ *   2. an outcome confirmed by an independent response (the service's own log)
 19→ *      or by a file the model read back is judged normally; an outcome that
 20→ *      cannot be separated stays unknown;
 21→ *   3. `&&`, conditionals, loops and concurrently issued calls do not let the
 22→ *      text order stand in for execution order or for "the last one";
 23→ *   4. a task request is recognised from the parsed action and request fields
 24→ *      (POST to the search path with the task query), never from the whole
 25→ *      command containing the marker, and never only when the address or the
 26→ *      trace happens to be the right one.
 27→ */
 28→
 29→import { test } from "node:test";
 30→import assert from "node:assert/strict";
 31→
 32→import { attempts, verify, PASS, FAIL, ERROR, TASK_MARKER } from "./verify.mjs";
 33→
 34→const B = "http://127.0.0.1:47318/skill-bridge/v3/skill/search";
 35→const A = "http://10.244.7.19:8096/skill-bridge/v3/skill/search";
 36→const curl = (url, trace, extra = "") => `curl -sSk ${extra} -X POST ${url} -H 'content-type: application/json' -H 'x-team-trace: ${trace}' -d '{"query": "${TASK_MARKER}"}'`;
 37→const OK_ENVELOPE = '{"code":0,"message":"ok","request_id":"req-1","data":{"items":[]}}';
 38→
 39→/**
 40→ * A captured session. Each step is one assistant message; `calls` are the tool
 41→ * calls it issued together, each with the command and the result text that came
 42→ * back. Timestamps follow batch 4: message k is produced at T0 + 10k seconds
 43→ * and its results are sent back 12 seconds later.
 44→ */
 45→function session(steps) {
 46→  const rows = [];
 47→  const messages = [{ role: "user", content: "do the task" }];
 48→  let t = Date.parse("2026-09-10T23:26:30Z");
 49→  let n = 0;
 50→  rows.push({ event: "http.request", requestId: "r0", timestamp: new Date(t).toISOString(), headers: { "x-conversation-id": "conv-1" }, body: { json: { messages: [...messages] } } });
 51→  for (const step of steps) {
 52→    t += 2000;
 53→    rows.push({ event: "http.response", requestId: `r${n}`, timestamp: new Date(t).toISOString(), body: { text: "" } });
 54→    const calls = step.calls.map((c, i) => ({ id: c.id ?? `c${n}_${i}`, ...c }));
 55→    messages.push({ role: "assistant", tool_calls: calls.map((c) => ({ id: c.id, function: { name: "Bash", arguments: JSON.stringify({ command: c.command }) } })) });
 56→    for (const c of calls) if (c.result !== undefined) messages.push({ role: "tool", tool_call_id: c.id, content: `Command: ${c.command}\n${c.result}` });
 57→    t += step.took ?? 12000; n += 1;
 58→    rows.push({ event: "http.request", requestId: `r${n}`, timestamp: new Date(t).toISOString(), headers: { "x-conversation-id": "conv-1" }, body: { json: { messages: [...messages] } } });
 59→  }
 60→  return rows;
 61→}
 62→
 63→/** Service-side rows, in the log's own local clock (UTC+8 on the batch host). */
 64→const local = (isoUtc, plusMs = 0) => {
 65→  const d = new Date(Date.parse(isoUtc) + plusMs + 8 * 3600 * 1000);
 66→  return d.toISOString().replace("T", " ").replace("Z", "");
 67→};
 68→const intentRow = (isoUtc, command) => ({ timestamp: local(isoUtc), kind: "model_intent", initiated_tool: "Bash", request_body: JSON.stringify({ command }) });
 69→const answeredRow = (isoUtc, plusMs, query = TASK_MARKER, status = 200) => ({ timestamp: local(isoUtc, plusMs), kind: "bridge_call", executed_endpoint: "search", upstream_status: status, elapsed_ms: 4, request_body: JSON.stringify({ query, team_id: "t" }) });
 70→const REACH = { targets: { "127.0.0.1:47318": { ok: true, why: "tcp connect ok" }, "10.244.7.19:8096": { ok: false, why: "timed out" } } };
 71→
 72→// ── boundary 1 & 4: what counts as a request ─────────────────────
 73→
 74→test("one command, two dials: two attempts in shell order, each with its own address and trace", () => {
 75→  const cmd = `${curl(B, "bt-fixtureright")}\necho\n${curl(A, "bt-fixturewrong")}`;
 76→  const got = attempts(session([{ calls: [{ command: cmd, result: `Stdout: ${OK_ENVELOPE}\nStderr: curl: (28) Connection timed out after 12003 milliseconds\nExit Code: 0` }] }]));
 77→  assert.deepEqual(got.map((a) => [`${a.host}:${a.port}`, a.value, a.request_index]), [["127.0.0.1:47318", "bt-fixtureright", 0], ["10.244.7.19:8096", "bt-fixturewrong", 1]]);
 78→  assert.ok(got.every((a) => a.call_id === got[0].call_id));
 79→});
 80→
 81→test("a search whose query merely contains the marker is not the task request; the task request is the one whose query IS the marker", () => {
 82→  const search = `curl -sSk -X POST http://127.0.0.1:8096/skill-bridge/v3/skill/search -d '{"query": "reachability check ${TASK_MARKER}"}'`;
 83→  assert.equal(attempts(session([{ calls: [{ command: search, result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` }] }])).length, 0);
 84→  assert.equal(attempts(session([{ calls: [{ command: curl(B, "bt-x"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` }] }])).length, 1);
 85→});
 86→
 87→test("a loop with a variable body is not identifiable as the task request and is reported, not counted", () => {
 88→  const loop = `for q in "a" "${TASK_MARKER}"; do curl -sSk -X POST ${B} -d "{\\"query\\": \\"$q\\"}"; done`;
 89→  const r = verify(session([{ calls: [{ command: loop, result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` }] }]));
 90→  assert.equal(r.attempts.length, 0);
 91→  assert.equal(r.verdict, ERROR);
 92→  assert.ok(r.problems.some((p) => /loop|not literal/i.test(p)), JSON.stringify(r.problems));
 93→});
 94→
 95→test("a request to the wrong address with the wrong trace is still a request — nothing filters on being right", () => {
 96→  const got = attempts(session([{ calls: [{ command: curl(A, "bt-fixturewrong"), result: "Stdout: \nStderr: curl: (28) Connection timed out after 20001 milliseconds\nExit code: 28" }] }]));
 97→  assert.equal(got.length, 1);
 98→  assert.equal(got[0].ok, false);
 99→});
100→
101→// ── boundary 2: outcomes only from evidence that separates them ──
102→
103→test("with nothing to separate them, two dials in one command are both unknown and the run is unjudgeable", () => {
104→  const cmd = `${curl(B, "bt-r")}\n${curl(A, "bt-w")}`;
105→  const r = verify(session([{ calls: [{ command: cmd, result: `Stdout: ${OK_ENVELOPE}\nStderr: curl: (28) Connection timed out after 12003 milliseconds\nExit Code: 0` }] }]));
106→  assert.deepEqual(r.attempts.map((a) => a.ok), [null, null]);
107→  assert.equal(r.verdict, ERROR);
108→  assert.match(r.reason, /not separable/);
109→});
110→
111→test("a file the model wrote with -o and read back in a later call confirms that request's outcome", () => {
112→  const cmd = `${curl(B, "bt-r", "-o /tmp/resp_b.txt")}\n${curl(A, "bt-w", "-o /tmp/resp_a.txt")}`;
113→  const cap = session([
114→    { calls: [{ command: cmd, result: "Stdout: HTTP=200\nHTTP=000\nStderr: curl: (28) Connection timed out\nExit Code: 0" }] },
115→    { calls: [{ command: `python3 -c 'import json; print(json.load(open("/tmp/resp_b.txt")))'`, result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` }] },
116→  ]);
117→  const got = attempts(cap);
118→  assert.equal(got[0].ok, true);
119→  assert.match(got[0].evidence.join(" "), /resp_b\.txt/);
120→  assert.equal(got[1].ok, null);
121→});
122→
123→test("the service's own log separates them: one answered row in the call's window binds the envelope to the only reachable address, the curl 28 to the only unreachable one, and shell order makes the last one decide", () => {
124→  const cmd = `${curl(B, "bt-r")}\necho\n${curl(A, "bt-w")}`;
125→  const cap = session([{ calls: [{ command: cmd, result: `Stdout: ${OK_ENVELOPE}\nHTTP=000\nStderr: curl: (28) Connection timed out after 12003 milliseconds\nExit Code: 0` }] }]);
126→  const t0 = cap.find((e) => e.event === "http.response").timestamp;
127→  const rows = [intentRow(t0, cmd), answeredRow(t0, 100)];
128→  const r = verify(cap, { serviceRows: rows, reachability: REACH });
129→  assert.deepEqual(r.attempts.map((a) => [`${a.host}:${a.port}`, a.ok, a.why]), [["127.0.0.1:47318", true, "code 0"], ["10.244.7.19:8096", false, "timed out"]]);
130→  assert.ok(r.attempts[0].executed_at, "the answered request carries the service time");
131→  assert.equal(r.verdict, FAIL);
132→  assert.match(r.reason, /10\.244\.7\.19:8096/);
133→});
134→
135→test("two answered requests with the same body: when every answer and every envelope agree they are both confirmed; when they disagree neither can be attributed", () => {
136→  const cmd = `${curl(B, "bt-r")}\n${curl("http://127.0.0.1:8096/skill-bridge/v3/skill/search", "bt-r2")}`;
137→  const reach = { targets: { "127.0.0.1:47318": { ok: true }, "127.0.0.1:8096": { ok: true } } };
138→  const agree = session([{ calls: [{ command: cmd, result: `Stdout: ${OK_ENVELOPE}${OK_ENVELOPE}\nExit Code: 0` }] }]);
139→  const t0 = agree.find((e) => e.event === "http.response").timestamp;
140→  const ra = verify(agree, { serviceRows: [intentRow(t0, cmd), answeredRow(t0, 50), answeredRow(t0, 90)], reachability: reach });
141→  assert.deepEqual(ra.attempts.map((a) => a.ok), [true, true]);
142→  const mixed = session([{ calls: [{ command: cmd, result: `Stdout: ${OK_ENVELOPE}{"code":40101,"message":"refused"}\nExit Code: 0` }] }]);
143→  const t1 = mixed.find((e) => e.event === "http.response").timestamp;
144→  const rm = verify(mixed, { serviceRows: [intentRow(t1, cmd), answeredRow(t1, 50), answeredRow(t1, 90)], reachability: reach });
145→  assert.deepEqual(rm.attempts.map((a) => a.ok), [null, null]);
146→  assert.equal(rm.verdict, ERROR);
147→});
148→
149→test("one request per call keeps the whole result as its outcome, as before", () => {
150→  const r = verify(session([{ calls: [{ command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` }] }]));
151→  assert.equal(r.verdict, PASS);
152→  assert.equal(r.attempts[0].ok, true);
153→});
154→
155→// ── boundary 3: order is not the text order ──────────────────────
156→
157→test("two calls issued in one model message with different outcomes have no last one: unjudgeable, with both outcomes on record", () => {
158→  const cap = session([{ calls: [
159→    { command: curl(A, "bt-w", "-m 20"), result: "Stdout: \nStderr: curl: (28) Connection timed out after 20001 milliseconds\nExit code: 28" },
160→    { command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` },
161→  ], took: 20200 }]);
162→  const r = verify(cap);
163→  assert.deepEqual(r.attempts.map((a) => a.ok), [false, true]);
164→  assert.equal(r.verdict, ERROR);
165→  assert.match(r.reason, /issued together|concurrent/);
166→  assert.deepEqual(r.final_batch, { ok: 1, failed: 1, unknown: 0 });
167→});
168→
169→test("two calls issued together whose outcomes agree are decided by that outcome", () => {
170→  const cap = session([{ calls: [
171→    { command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` },
172→    { command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` },
173→  ] }]);
174→  assert.equal(verify(cap).verdict, PASS);
175→});
176→
177→test("a later message is later: a failure in an earlier message and a success in the last one is a pass", () => {
178→  const cap = session([
179→    { calls: [{ command: curl(A, "bt-w"), result: "Stdout: \nStderr: curl: (28) Connection timed out\nExit code: 28" }] },
180→    { calls: [{ command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` }] },
181→  ]);
182→  const r = verify(cap);
183→  assert.equal(r.verdict, PASS);
184→  assert.match(r.reason, /after 1 earlier failure/);
185→});
186→
187→test("a backgrounded request in the final call has no order even when its outcome is known", () => {
188→  const cmd = `${curl(A, "bt-w")} &\n${curl(B, "bt-r")}\nwait`;
189→  const r = verify(session([{ calls: [{ command: cmd, result: `Stdout: ${OK_ENVELOPE}\nStderr: curl: (28) Connection timed out\nExit Code: 0` }] }]));
190→  assert.equal(r.verdict, ERROR);
191→});
192→
193→test("the verdict names its parser version", () => {
194→  const r = verify(session([{ calls: [{ command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` }] }]));
195→  assert.match(r.acceptance_version, /^attempts-2026-09-11/);
196→});
